static unsigned traits_of(const MinifyHtmlTraits *rows, size_t n, unsigned long hash)
{
    size_t lo = 0;
    size_t hi = n;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;

        if (rows[mid].hash == hash) return rows[mid].traits;
        if (rows[mid].hash < hash) lo = mid + 1;
        else hi = mid;
    }
    return 0;
}

unsigned minify_html_tag_traits(unsigned long hash)
{
    return traits_of(tag_traits, sizeof tag_traits / sizeof tag_traits[0], hash);
}

unsigned minify_html_attr_traits(unsigned long hash)
{
    return traits_of(attr_traits, sizeof attr_traits / sizeof attr_traits[0], hash);
}

/* table.go jsMimetypes */
int minify_html_js_mimetype(const unsigned char *s, size_t n)
{
    if (n == 15 && memcmp(s, "text/javascript", 15) == 0) return 1;
    if (n == 22 && memcmp(s, "application/javascript", 22) == 0) return 1;
    return 0;
}

