const MinifyEntity *minify_html_entity(const unsigned char *name, size_t n)
{
    size_t lo = 0;
    size_t hi = ENTITY_COUNT;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        const MinifyEntity *e = &entities[mid];
        size_t k = n < e->name_len ? n : e->name_len;
        int c = memcmp(name, e->name, k);

        if (c == 0) {
            if (n == e->name_len) return e;
            c = n < e->name_len ? -1 : 1;
        }
        if (c < 0) hi = mid;
        else lo = mid + 1;
    }
    return NULL;
}
